// Explicit native-schema peer, NOT Rust fg. The fixture bundle and object
// identities are generated by installed Git only in this nonproduction test.
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { createServer } from 'node:http';
import { createHash } from 'node:crypto';
export const TOKEN = 'a'.repeat(64), PRINCIPAL = '4'.repeat(32);
export const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const repositories = new Map();
function repo(format) {
  if (repositories.has(format)) return repositories.get(format);
  const dir = mkdtempSync(join(tmpdir(), 'fg-source-edit-'));
  try {
    const git = (args, input) => execFileSync('git', ['-C', dir, ...args], { input, env: { ...process.env, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: '/dev/null' } }).toString().trim();
    git(['init', '--quiet', `--object-format=${format}`]);
    const write = (kind, bytes) => git(['hash-object', '-w', '-t', kind, '--stdin'], bytes);
    const beforeTree = write('tree', Buffer.alloc(0));
    const base = write('commit', Buffer.from(`tree ${beforeTree}\nauthor Example <e@example.invalid> 1 +0000\ncommitter Example <e@example.invalid> 1 +0000\n\nbase\n`));
    const data = Buffer.from('hello\r\n'), blob = write('blob', data);
    const tree = write('tree', Buffer.concat([Buffer.from('100644 file\0'), Buffer.from(blob, 'hex')]));
    const metadata = { author: 'Example <e@example.invalid>', committer: 'Example <e@example.invalid>', timestamp: 2, message: 'change\n' };
    const body = Buffer.from(`tree ${tree}\nparent ${base}\nauthor ${metadata.author} 2 +0000\ncommitter ${metadata.committer} 2 +0000\n\n${metadata.message}`);
    const candidate = write('commit', body); git(['update-ref', 'refs/heads/main', candidate]);
    git(['bundle', 'create', join(dir, 'candidate.bundle'), 'refs/heads/main', `^${base}`]);
    const bundle = readFileSync(join(dir, 'candidate.bundle'));
    const value = { base, beforeTree, tree, data, blob, body, candidate, metadata, bundle }; repositories.set(format, value); return value;
  } finally { rmSync(dir, { recursive: true, force: true }); }
}
export async function peer(t, format = 'sha1') {
  const r = repo(format), calls = [], control = {}, scope = { tenant_id: '1'.repeat(32), repository_id: '2'.repeat(32), repository_incarnation: '3'.repeat(32), object_format: format };
  const patch = Buffer.from('diff --git a/file b/file\nnew file mode 100644\n--- /dev/null\n+++ b/file\n@@ -0,0 +1 @@\n+hello\r\n');
  const oid = id => `${format}:${id}`, ref = 'refs/heads/main';
  const common = { schema_version: 1, ...scope, ref, ref_hex: Buffer.from(ref).toString('hex'),
    read_only: true, objects_staged: false, transaction_created: false, published: false, publication_authorized: false };
  const preparation = { type: 'source_preparation', ...common, source_commit: oid(r.base), source_rcr: 'fixture-rcr', candidate_commit: oid(r.candidate),
    root_tree: oid(r.tree), patch_sha256: digest(patch), object_count: 3, bundle: { bytes: r.bundle.length, sha256: digest(r.bundle) },
    paths: [{ path_hex: '66696c65', old_blob: null, new_blob: oid(r.blob), new_mode: 0o100644, hunks: 1 }] };
  const inspection = { type: 'source_inspection', ...common, source_head: 'fixture-head', snapshot_token: `alg:2:${'5'.repeat(64)}`,
    expected_commit: oid(r.base), candidate_commit: oid(r.candidate), parents: [oid(r.base)], bundle_bytes: r.bundle.length, bundle_sha256: digest(r.bundle),
    all_changed_paths: true, binary_bodies_included: false, candidate_commit_body_hex: r.body.toString('hex'),
    comparison: { mode: 'direct', before_tree: oid(r.beforeTree), after_tree: oid(r.tree), entry_count: 1,
      entries: [{ path_hex: '66696c65', kind: 'added', before: null, after: { mode: 0o100644, oid: oid(r.blob) }, content: {
        type: 'text', algorithm: 'Myers', additions: 1, deletions: 0, before_bytes: 0, after_bytes: r.data.length,
        hunks: [{ old: { byte_start: 0, byte_end: 0, line_start: 0, line_count: 0 },
          new: { byte_start: 0, byte_end: r.data.length, line_start: 0, line_count: 1 }, before_hex: '', after_hex: r.data.toString('hex') }] } }] } };
  const frame = (metadata = preparation, bundle = r.bundle) => {
    const b = `fg-source-${digest(bundle).slice(0, 48)}-0`;
    return { type: `multipart/mixed; boundary=${b}`, bytes: Buffer.concat([
      Buffer.from(`--${b}\r\nContent-Type: application/json; charset=utf-8\r\nContent-Disposition: inline; name="metadata"\r\n\r\n${JSON.stringify(metadata)}\r\n--${b}\r\nContent-Type: application/x-git-bundle\r\nContent-Disposition: attachment; name="bundle"; filename="candidate.bundle"\r\n\r\n`), bundle, Buffer.from(`\r\n--${b}--\r\n`)]) };
  };
  const sockets = new Set();
  const server = createServer(async (req, res) => {
    try {
      const chunks = []; for await (const b of req) chunks.push(b);
      const body = Buffer.concat(chunks), operation = req.url.split('/').at(-1);
      const call = { operation, headers: req.headers, body, method: req.method }; calls.push(call);
      if (control.handler) { await control.handler(req, res, call); return; }
      if (req.headers.authorization !== `Bearer ${TOKEN}` || req.headers['idempotency-key']) { res.writeHead(403); res.end('{}'); return; }
      if (control.status) { res.writeHead(control.status, { Location: '/leak' }); res.end('{}'); return; }
      const reply = structuredClone(operation === 'prepare' ? preparation : inspection); await control.mutate?.(reply, call);
      const data = operation === 'prepare' ? frame(reply) : { type: 'application/json', bytes: Buffer.from(JSON.stringify(reply)) };
      control.wire?.(data, call); res.writeHead(200, { 'Content-Type': data.type }); res.end(data.bytes);
    } catch { res.destroy(); }
  });
  server.on('connection', s => { sockets.add(s); s.on('close', () => sockets.delete(s)); });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  t.after(async () => { for (const s of sockets) s.destroy(); await new Promise(resolve => server.close(resolve)); });
  return { ...r, patch, preparation, inspection, frame, calls, control, server, sockets,
    request: { endpoint: `http://127.0.0.1:${server.address().port}/repo.git`, scope, ref, expected_commit: r.base, metadata: structuredClone(r.metadata), paths_hex: ['66696c65'] } };
}
